import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static String next() throws IOException {
        int c = skipSpaces();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        // 1 (the original) plus the number of index pairs whose characters differ.
        long[] seen = new long[26];
        long answer = 1;
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            answer += i - seen[c];
            seen[c]++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	// 1 (the original) plus the number of index pairs whose characters differ.
	var seen [26]int
	answer := 1
	for i, ch := range next() {
		answer += i - seen[ch-'a']
		seen[ch-'a']++
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
